const FINAL_TO_MEDIAL: Record<string, string> = { ן: "נ", ך: "כ", ם: "מ", ף: "פ", ץ: "צ" };

const PERFECT_FOLDED: Record<string, ParadigmVerse> = {};
for (const [key, verse] of Object.entries(PERFECT_BY_LETTERS)) PERFECT_FOLDED[foldLetters(key)] = verse;

function foldLetters(letters: string): string {
  return [...letters]
    .filter((ch) => {
      const cp = ch.codePointAt(0) ?? 0;
      return cp >= 0x05d0 && cp <= 0x05ea;
    })
    .map((ch) => FINAL_TO_MEDIAL[ch] || ch)
    .join("");
}

export function paradigmVerse(rootId: string, stem: string, conj: string): ParadigmVerse | null {
  return PARADIGM_VERSES[rootId + ":" + stem + ":" + conj] ?? null;
}

export function perfectVerse(letters: string): ParadigmVerse | null {
  return PERFECT_FOLDED[foldLetters(letters)] ?? null;
}
